import{_ as l,l as i,o as e,c as n,v as t,p as s,x as o,d as p,i as d,S as A}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"列存与 PAX","description":"","frontmatter":{"title":"列存与 PAX","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/columnar-pax.md","filePath":"cs/columnar-pax.md","lastUpdated":1789023840000}'),c={name:"cs/columnar-pax.md"};function h(E,a,P,u,m,_){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="列存与-pax" tabindex="-1">列存与 PAX <a class="header-anchor" href="#列存与-pax" aria-label="Permalink to &quot;列存与 PAX&quot;">​</a></h1><div class="epigraph"><p>列存按属性切文件，扫描只读需要的列；PAX 在页内按列摆放，保持页为 I/O 单位，减少行组装的跨页随机。</p><footer>—— 据 Copeland and Khoshafian DSM；Ailamaki et al. PAX, VLDB 2001；C-Store / MonetDB</footer></div><p><a href="/cs/leveled-tiered-compaction">上一课</a>决定 LSM 文件如何分层。本课不调倍率。缺口是页/文件<strong>内部布局</strong>：行存一行连续，OLAP 扫描浪费带宽在无用列上。列存（DSM）每列一堆文件，延迟物化自然。PAX（partition attributes across）折中：一页里所有列的一段行，页间仍是行组。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分析查询常 <code>SUM(a) WHERE b&gt;</code>，只需两列。行页把整行带进缓存。纯列存：谓词列与度量列分别顺序扫，组装用位置对齐。跨列更新、点查、宽行插入在纯列上变随机或写放大。缺口是 <strong>OLAP 布局 vs OLTP 行页</strong>，不是新 SQL。</p><p>PAX：一个 row group 放进页，页内各列分别数组。缓存行上扫一列仍顺序，点查一行在同一页内可取齐列。C-Store、Parquet 的 row group 是同一思想的文件级版本。</p><p><span class="marginnote">Ailamaki, DeWitt, Hill, Skounakis，VLDB 2001 PAX。Copeland and Khoshafian 分解存储模型。Stonebraker et al. C-Store。本课布局；压缩下一课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>行页：槽+记录。列文件：每列块+位置对齐或每列自有空值位图。PAX 页：页头、各列偏移、列数据。执行器向量化从 PAX 或列块直接填列向量，少经行中间态。</p><p>HTAP 后课用两份或可更新列存；本课只钉只读分析布局的动机。</p>',10)),(e(),s(A,null,{default:o(()=>[d(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20NSM%5B%22%E8%A1%8C%E9%A1%B5%22%5D%20--%3E%20WIDE%5B%22%E6%89%AB%E8%A1%8C%E5%B8%A6%E4%B8%8A%E6%97%A0%E7%94%A8%E5%88%97%22%5D%0A%20%20DSM%5B%22%E5%88%97%E6%96%87%E4%BB%B6%22%5D%20--%3E%20NARROW%5B%22%E5%8F%AA%E8%AF%BB%E9%9C%80%E8%A6%81%E7%9A%84%E5%88%97%22%5D%0A%20%20PAX%5B%22%E9%A1%B5%E5%86%85%E5%88%97%22%5D%20--%3E%20MIX%5B%22I%2FO%20%E5%8D%95%E4%BD%8D%E4%BB%8D%E6%98%AF%E9%A1%B5%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>更新：行页原地或 MVCC 新行；列存常写新列块或 delta 再合并（LSM+列）。缓冲池：列块缓存与行页缓存权重不同，替换策略仍要抗扫描污染。</p><p>连接：列存上延迟物化用位置；shuffle 只发键列。与 exchange 课对齐。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲字典/RLE。也不把宽列 Bigtable 当分析列存——宽列是稀疏行键模型，后课。PAX 不是「有了就不需要 Parquet」；文件格式课会把 row group 标准化。</p><p>后课默认：分析扫描用列或 PAX；点查可用行或覆盖索引。列压缩：编码使列块更小、跳过更狠。</p><p>布局服务访问模式。同一 SQL 在不同布局上计划常数不同，要重校准。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>列存减分析 I/O；PAX 在页内列化以免点查跨页。</li><li>更新与点查是列存的代价面。</li><li>列压缩下一课：字典、RLE、位打包。</li><li>出处：Copeland and Khoshafian；Ailamaki et al. PAX；C-Store。</li></ul>',9))])}const S=l(c,[["render",h]]);export{f as __pageData,S as default};
